<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center"><div><div class="text-overline">SALES CRM</div><h1 class="text-h5 font-weight-bold">Site Visits</h1><div class="grey--text">Schedule and monitor property visits.</div></div><v-spacer/><v-btn v-if="$can('site_visits.create')" color="#165134" dark @click="open"><v-icon left>mdi-calendar-plus</v-icon>Schedule Visit</v-btn></div></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading"><template v-slot:item.visit_at="{item}">{{formatDate(item.visit_at)}}</template><template v-slot:item.status="{item}"><v-chip x-small :color="statusColor(item.status)" dark>{{item.status}}</v-chip></template><template v-slot:item.actions="{item}"><v-btn v-if="$can('site_visits.edit')" icon small @click="edit(item)"><v-icon small>mdi-pencil</v-icon></v-btn><v-btn v-if="$can('site_visits.delete')" icon small color="error" @click="remove(item)"><v-icon small>mdi-delete-outline</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="650"><v-card><v-card-title>{{editing?'Edit Site Visit':'Schedule Site Visit'}}<v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-autocomplete v-model="form.customer_id" :items="customers" item-text="name" item-value="id" outlined dense clearable label="Customer" :loading="loadingCustomers" prepend-inner-icon="mdi-account"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.property_id" :items="properties" item-text="property_number" item-value="id" outlined dense clearable label="Property" :loading="loadingProperties" prepend-inner-icon="mdi-home-city"><template v-slot:item="{item}"><v-list-item-content><v-list-item-title>{{item.property_number}} — {{item.project ? item.project.name : 'Property'}}</v-list-item-title><v-list-item-subtitle>{{item.status}}</v-list-item-subtitle></v-list-item-content></template></v-autocomplete></v-col><v-col cols="12" md="6"><v-text-field v-model="form.visit_date" outlined dense type="date" label="Visit Date *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.visit_time" outlined dense type="time" label="Time"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn v-if="editing ? $can('site_visits.edit') : $can('site_visits.create')" color="#165134" dark :loading="saving" :disabled="!form.customer_id || !form.visit_date" @click="save">{{editing?'Update':'Schedule'}}</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'SiteVisits',data(){return{loading:false,saving:false,dialog:false,editing:null,items:[],customers:[],properties:[],loadingCustomers:false,loadingProperties:false,headers:[{text:'Customer',value:'customer.name'},{text:'Property',value:'property.property_number'},{text:'Visit',value:'visit_at'},{text:'Status',value:'status'},{text:'Notes',value:'notes'},{text:'Actions',value:'actions',sortable:false}],form:{customer_id:null,property_id:null,visit_date:'',visit_time:'',notes:''}}},mounted(){this.load()},methods:{async loadLookups(){this.loadingCustomers=true;this.loadingProperties=true;try{const[c,p]=await Promise.all([api.get('/customers',{params:{per_page:100}}),api.get('/properties',{params:{per_page:100}})]);this.customers=c.data.data||[];this.properties=p.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load visit selections.')}finally{this.loadingCustomers=false;this.loadingProperties=false}},async load(){this.loading=true;try{const r=await api.get('/site-visits',{params:{per_page:100}});this.items=r.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load site visits.')}finally{this.loading=false}},open(){this.editing=null;this.form={customer_id:null,property_id:null,visit_date:new Date().toISOString().slice(0,10),visit_time:'10:00',notes:''};this.dialog=true;this.loadLookups()},edit(item){this.editing=item;const d=item.visit_at?new Date(item.visit_at):new Date();this.form={customer_id:item.customer_id||null,property_id:item.property_id||null,visit_date:d.toISOString().slice(0,10),visit_time:d.toTimeString().slice(0,5),notes:item.notes||''};this.dialog=true;this.loadLookups()},async save(){this.saving=true;try{const visit_at=this.form.visit_date+' '+(this.form.visit_time||'00:00');const payload={customer_id:this.form.customer_id,property_id:this.form.property_id||null,visit_at,status:this.editing?(this.editing.status||'scheduled'):'scheduled',notes:this.form.notes};if(this.editing)await api.put('/site-visits/'+this.editing.id,payload);else await api.post('/site-visits',payload);this.dialog=false;await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to save site visit.')}finally{this.saving=false}},async remove(item){if(!window.confirm('Delete this site visit?'))return;try{await api.delete('/site-visits/'+item.id);await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to delete site visit.')}},formatDate(v){return v?new Date(v).toLocaleString('en-PK',{dateStyle:'medium',timeStyle:'short'}):'-'},statusColor(s){return{scheduled:'orange',completed:'success',cancelled:'grey',no_show:'error'}[s]||'grey'}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>